SELECT 'all 28 creatures are in' AS assertion, count(*) AS got, 28 AS want
  FROM creatures WHERE slug IN ('black-winged-monster-men', 'man-eagles', 'animal-man-monster', 'plant-man-monster', 'spirit-man-monster', 'hunter-great-little-ones', 'stone-thrower-great-little-ones', 'nurturer-great-little-ones', 'plumed-serpents', 'stone-giants', 'teepowka', 'two-faced-star-people', 'ukt-water-serpents', 'wendigo', 'lesser-animal-spirits', 'lesser-plant-spirits', 'lesser-elemental-spirits', 'kachina-tectonic-spirit', 'lesser-kachina-spirit', 'great-kachina-spirits', 'ondi-thunderbirds', 'greater-air-spirit', 'greater-earth-spirit', 'greater-fire-spirit', 'greater-water-spirit', 'greater-totem-animal-spirits', 'tree-spirits', 'nunnehi');
